def merge_duplicate_applications(apps, schema_editor):
    """
    1차에는 중복 신청을 막지 않아서 같은 교육·같은 이메일(대소문자 무시) 신청이 쌓여 있을 수 있다.
    유니크 제약을 걸기 전에 정리한다: 가장 먼저 들어온 신청을 남기고, 나중 신청의 내용은
    남긴 신청의 담당자 메모에 기록한 뒤 지운다(정보를 잃지 않게). 상태는 가장 진행된 것을 따른다.
    """
    Application = apps.get_model("applications", "Application")
    order = {"received": 0, "reviewing": 1, "done": 2}
    groups = {}
    for a in Application.objects.order_by("created_at", "id"):
        groups.setdefault((a.course_id, a.email.strip().lower()), []).append(a)
    for (_, email), rows in groups.items():
        keep, extra = rows[0], rows[1:]
        keep.email = email
        if extra:
            notes = [
                f"[중복 신청 병합] {r.created_at:%Y-%m-%d %H:%M} 신청 #{r.id}: "
                f"{r.name} / {r.address} {r.address_detail} / 연락 {r.contact_date}"
                for r in extra
            ]
            keep.admin_memo = "\n".join(filter(None, [keep.admin_memo, *notes]))
            best = max([keep, *extra], key=lambda r: order.get(r.status, 0))
            keep.status = best.status
            Application.objects.filter(pk__in=[r.pk for r in extra]).delete()
        keep.save(update_fields=["email", "admin_memo", "status"])


